export function BidirectionalText({
  leadText = "{{leadText}}",
  rtlPhrase = "{{rtlPhrase}}",
  trailText = "{{trailText}}",
  isolate = {{isolate}},
}) {
  const lineStyle = { margin: "0 0 10px", padding: "10px 12px", borderRadius: 8, background: "#ffffff", border: "1px solid #24143018" };
  return (
    <div style={{ font: "16px/1.7 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, width: 320, boxSizing: "border-box" }}>
      {isolate
        ? <p style={lineStyle}>{leadText} &mdash; <bdi>{rtlPhrase}</bdi> &mdash; {trailText}</p>
        : <p style={lineStyle}>{leadText} &mdash; <span>{rtlPhrase}</span> &mdash; {trailText}</p>}
      <p style={{ margin: "8px 0 0", fontSize: 11, color: "#24143099" }}>
        {isolate ? "<bdi> isolates the Arabic run so surrounding Latin punctuation keeps its own order." : "Without <bdi>, the Unicode bidi algorithm can pull neighbouring punctuation into the Arabic run."}
      </p>
    </div>
  );
}
